using System;
using System.Collections.Generic;
using System.IO;
using Gazik.Core;

static class Checks
{
    const double Now=1792627200000;
    static int count;static Catalog catalog;
    static void Check(string name,Action action){action();count++;Console.WriteLine("PASS "+name);}
    static void Assert(bool value,string reason="Assertion failed"){if(!value)throw new Exception(reason);}
    static void Near(double a,double b){Assert(Math.Abs(a-b)<.0001,a+" != "+b);}
    static GameRules Rules(PetState s=null)=>new GameRules(s??PetState.Fresh(Now),catalog,123,PetState.Day){CanWrite=true};
    static int Main(string[] args)
    {
        try
        {
            catalog=Catalog.Load(File.ReadAllText(args[0]));
            Check("Original catalog and letters remain alongside new unlocks",()=>{Assert(catalog.Shop.Count==26&&catalog.Letters.Count==20);Assert(catalog.Shop.Find(x=>x.Id=="crown").Cost==45);Assert(catalog.Shop.Find(x=>x.Id=="cape").MinStage==3);});
            Check("JSON unicode, controls and unknown fields round-trip",()=>{var s=PetState.Fresh(Now);s.Set("name","Газик 🦔 \"Звёздочка\"\n");s.Set("futureData",Json.Parse("{\"nested\":[true,null,1.25e4]}"));var copy=PetState.FromJson(s.ToJson());Assert(copy.Name==s.Name);Assert(Json.Stringify(copy.Data["futureData"])==Json.Stringify(s.Data["futureData"]));});
            Check("JSON malformed input is refused",()=>{foreach(string s in new[]{"{","[1,]","{\"x\":01}","{\"x\":1.}","null x","\"\\q\"","1e9999"}){bool bad=false;try{Json.Parse(s);}catch(FormatException){bad=true;}Assert(bad,s);}});
            Check("Readonly care is a complete no-op",()=>{var r=Rules();r.CanWrite=false;string before=r.State.ToJson();Assert(!r.Care("feed",Now).Ok);Assert(before==r.State.ToJson());});
            Check("Readonly shop, rename, game rewards are refused",()=>{var r=Rules();r.CanWrite=false;string before=r.State.ToJson();Assert(!r.Shop("ball",Now).Ok&&!r.Rename("Друг",Now).Ok&&!r.AwardGame("memory",4,Now).Ok);Assert(before==r.State.ToJson());});
            Check("Tired play does not grant rewards or start cooldown",()=>{var r=Rules();r.State.Stat("energy",5);string before=r.State.ToJson();Assert(!r.Care("play",Now).Ok);Assert(before==r.State.ToJson());});
            Check("Feed raises needs and sets cooldown",()=>{var r=Rules();r.State.Stat("hunger",30);Assert(r.Care("feed",Now).Ok);Near(r.State.Stat("hunger"),64);string saved=r.State.ToJson();Assert(!r.Care("feed",Now+1).Ok);Assert(saved==r.State.ToJson());});
            Check("Cooldown expires at the exact boundary",()=>{var r=Rules();r.Care("feed",Now);Assert(!r.Care("feed",Now+GameRules.Hour*1.5-1).Ok);Assert(r.Care("feed",Now+GameRules.Hour*1.5).Ok);});
            Check("Sleep blocks care and splits offline decay",()=>{var r=Rules();r.State.Stat("energy",40);Assert(r.Care("sleep",Now).Ok);Assert(!r.Care("bath",Now+100).Ok);var s=r.View(Now+2*GameRules.Hour);Near(s.Stat("energy"),47.5);Near(s.Stat("hunger"),85.3875);Assert(!s.Sleeping(Now+2*GameRules.Hour));});
            Check("Offline values remain clamped",()=>{var s=PetState.Fresh(Now);GameRules.Decay(s,Now+1000*GameRules.Hour);foreach(string k in new[]{"hunger","fun","clean","energy"})Near(s.Stat(k),0);});
            Check("Clock rollback cannot advance decay",()=>{var s=PetState.Fresh(Now);string before=s.ToJson();GameRules.Decay(s,Now-10000);Assert(before==s.ToJson());});
            Check("A complete care day grants one forced letter",()=>{var r=Rules();foreach(string a in GameRules.Actions)Assert(r.Care(a,Now).Ok);Assert(r.State.List("letters").Count>=1);Assert((bool)r.State.Map("daily")["bonusClaimed"]);Near(r.State.Number("growthXp"),18);string before=r.State.ToJson();Assert(!r.Care("sleep",Now+5).Ok);Assert(before==r.State.ToJson());});
            Check("Daily key resets across local midnight",()=>{var r=Rules();r.EnsureDay(Now);((List<object>)r.State.Map("daily")["actions"]).Add("feed");r.EnsureDay(Now+86400000);Assert(((List<object>)r.State.Map("daily")["actions"]).Count==0);});
            Check("Unaffordable purchase cannot spend or equip",()=>{var r=Rules();string before=r.State.ToJson();Assert(!r.Shop("crown",Now).Ok);Assert(before==r.State.ToJson());});
            Check("Outfit toggles without duplicate ownership or double charges",()=>{var r=Rules();r.State.Set("stars",100);r.Shop("scarf",Now);Near(r.State.Number("stars"),88);r.Shop("scarf",Now);Near(r.State.Number("stars"),88);Assert(r.State.Equipped("outfit")==""&&r.State.List("owned").Count==1);r.Shop("scarf",Now);Assert(r.State.Equipped("outfit")=="scarf");});
            Check("Owned decor toggles from inventory without a second charge",()=>{var r=Rules();r.State.Set("stars",100);Assert(r.Shop("lamp",Now).Ok);Assert(r.Shop("lamp",Now).Ok&&r.State.List("hiddenDecor").Contains("lamp"));Near(r.State.Number("stars"),85);Assert(r.Shop("lamp",Now).Ok&&!r.State.List("hiddenDecor").Contains("lamp"));Near(r.State.Number("stars"),85);Assert(r.State.List("owned").Count==1);});
            Check("Treat purchase and use have separate effects",()=>{var r=Rules();r.State.Set("stars",100);r.State.Stat("hunger",20);r.Shop("moonberry",Now);Near(PetState.N(r.State.Map("consumables"),"moonberry"),1);var result=r.Shop("moonberry",Now);Assert(result.Animation=="float");Near(r.State.Stat("hunger"),31);Near(r.State.Number("stars"),86);Near(PetState.N(r.State.Map("consumables"),"moonberry"),0);});
            Check("Game reward only once per cooldown",()=>{var r=Rules();Assert(r.AwardGame("memory",4,Now).Ok);Near(r.State.Number("stars"),8);Assert(!r.AwardGame("memory",4,Now+1000).Ok);Assert(r.AwardGame("memory",4,Now+GameRules.GameCooldown).Ok);});
            Check("Impossible game scores are rejected",()=>{var r=Rules();Assert(!r.AwardGame("toss",6,Now).Ok&&!r.AwardGame("catch",-1,Now).Ok&&!r.AwardGame("memory",3,Now).Ok);Assert(r.AwardGame("toss",0,Now).Ok);Near(r.State.Number("stars"),5);});
            Check("Growth boundaries and bonus are stable",()=>{Assert(GameRules.Stage(34)==0&&GameRules.Stage(35)==1&&GameRules.Stage(280)==4);var r=Rules();r.State.Set("growthXp",34);r.AwardGame("memory",4,Now);Near(r.State.Number("growthXp"),35);Near(r.State.Number("stars"),11);});
            Check("Unknown imported fields survive gameplay",()=>{var r=Rules();r.State.Set("legacyExtra",Json.Parse("{\"v\":42}"));r.Care("feed",Now);Assert(Json.Stringify(r.State.Data["legacyExtra"])=="{\"v\":42}");});
            Check("Rename validation preserves the old name",()=>{var r=Rules();Assert(!r.Rename("   ",Now).Ok&&!r.Rename("Я",Now).Ok&&!r.Rename(new string('Я',19),Now).Ok);Assert(r.State.Name=="Газик");Assert(r.Rename(" Звёздный  Газик ",Now).Ok);Assert(r.State.Name=="Звёздный Газик");});
            Check("Partial imported save receives defaults and retains values",()=>{var s=PetState.FromJson("{\"stats\":{\"hunger\":42},\"equipped\":{\"toy\":\"ball\"},\"future\":5}");s.Normalize(Now);Near(s.Stat("hunger"),42);Near(s.Stat("fun"),88);Assert(s.Equipped("toy")=="ball"&&s.Equipped("outfit")==""&&s.Number("future")==5);});
            Check("Malformed imported letter entries and daily key cannot break care",()=>{var r=Rules();r.State.List("letters").AddRange(new object[]{null,"bad",true,2.5,3});Assert(r.State.HasLetter(3)&&!r.State.HasLetter(0)&&!r.State.HasLetter(2));r.State.Map("daily")["key"]=99;foreach(string a in GameRules.Actions)Assert(r.Care(a,Now).Ok);});
            Check("Renaming does not erase offline need decay",()=>{var r=Rules();Assert(r.Rename("Газик",Now+GameRules.Hour).Ok);Near(r.State.Stat("hunger"),87);Near(r.State.Stat("energy"),87.9);});
            Check("Daily summary ignores duplicates and unknown actions",()=>{var r=Rules();r.State.Map("daily")["actions"]=new List<object>{"feed","feed","bad","bath",null};string raw=r.State.ToJson();var v=HomeSummary.Read(r.State,Now,catalog);Assert(v.Count==2&&v.Done[0]&&v.Done[2]&&!v.Done[1]);Assert(raw==r.State.ToJson());});
            Check("Daily summary clears at midnight without changing stored history",()=>{var r=Rules();r.Care("feed",Now);var v=HomeSummary.Read(r.State,Now+86400000,catalog);Assert(v.Count==0&&v.DailyMessage.Contains("+8"));});
            Check("Growth progress is relative to current stage and caps at maximum",()=>{var s=PetState.Fresh(Now);s.Set("growthXp",62.5);Near(HomeSummary.Read(s,Now,catalog).Growth,.5);s.Set("growthXp",10000);var v=HomeSummary.Read(s,Now,catalog);Near(v.Growth,1);Assert(v.GrowthMessage=="максимальный рост ✦");});
            Check("Summary counts unique valid letters only",()=>{var s=PetState.Fresh(Now);s.List("letters").AddRange(new object[]{0,0,2,99,"bad"});Assert(HomeSummary.Read(s,Now,catalog).LetterCount==2);});
            Check("Sleeping status and age survive offline view",()=>{var s=PetState.Fresh(Now);s.Set("bornAt",Now-86400000);s.Set("sleepUntil",Now+60000);var v=HomeSummary.Read(s,Now,catalog);Assert(v.AgeDays==2&&v.MoodMessage.Contains("сладко спит"));});
            Check("Save journal rotates a valid previous generation",()=>{var storage=new Dictionary<string,string>();var j=Journal(storage,"local");var s=PetState.Fresh(Now);j.Save(s);string first=storage["local"];s.Set("stars",7);j.Save(s);Assert(storage["local.previous"]==first);Near(j.Load(Now,out bool recovered).Number("stars"),7);Assert(!recovered);});
            Check("Corrupt main save restores previous and retains damaged input",()=>{var storage=new Dictionary<string,string>{{"local","{bad"},{"local.previous",PetState.Fresh(Now).ToJson()}};var j=Journal(storage,"local");var s=j.Load(Now,out bool recovered);Assert(recovered&&storage["local.corrupt"]=="{bad");j.Save(s);Assert(storage["local.previous"]==s.ToJson());});
            Check("Invalid backup import leaves all generations unchanged",()=>{var storage=new Dictionary<string,string>();var j=Journal(storage,"local");var s=PetState.Fresh(Now);j.Save(s);string raw=Json.Stringify(new Dictionary<string,object>{{"main",storage["local"]}});bool failed=false;try{j.Import("{}",s,Now);}catch(FormatException){failed=true;}Assert(failed&&!storage.ContainsKey("local.before-import")&&Json.Stringify(new Dictionary<string,object>{{"main",storage["local"]}})==raw);});
            Check("Valid import backs up current state and keeps unknown fields",()=>{var storage=new Dictionary<string,string>();var j=Journal(storage,"local");var before=PetState.Fresh(Now);j.Save(before);var next=before.Clone();next.Set("stars",42);next.Set("future",Json.Parse("{\"v\":9}"));j.Import(next.ToJson(),before,Now);Assert(storage["local.before-import"]==before.ToJson());var loaded=j.Load(Now,out _);Near(loaded.Number("stars"),42);Assert(Json.Stringify(loaded.Data["future"])=="{\"v\":9}");});
            Check("Local and cloud journals cannot replace each other",()=>{var storage=new Dictionary<string,string>();var local=Journal(storage,"local");var cloud=Journal(storage,"cloud");var s=PetState.Fresh(Now);local.Save(s);s.Set("stars",100);cloud.Save(s);Near(local.Load(Now,out _).Number("stars"),4);Near(cloud.Load(Now,out _).Number("stars"),100);});
            Check("UTF-8 BOM backups are accepted and oversized files rejected",()=>{var s=SaveJournal.Parse("\uFEFF"+PetState.Fresh(Now).ToJson(),Now);Assert(s.Name=="Газик");bool failed=false;try{SaveJournal.Parse(new string(' ',2*1024*1024+1),Now);}catch(FormatException){failed=true;}Assert(failed);});
            Check("Starting or cancelling care cannot mutate save or grant rewards",()=>{var r=Rules();string before=r.State.ToJson();foreach(string a in GameRules.Actions)Assert(r.CanStartCare(a,Now).Ok);Assert(before==r.State.ToJson());r.CanWrite=false;Assert(!r.CanStartCare("feed",Now).Ok&&before==r.State.ToJson());});
            Check("Affection grows through care and is not lost during absence",()=>{var r=Rules();r.Care("feed",Now);Near(r.State.Number("affection"),2);Near(r.View(Now+1000*GameRules.Hour).Number("affection"),2);Assert(r.Bond(Now));double affection=r.State.Number("affection");Assert(!r.Bond(Now+10));Near(r.State.Number("affection"),affection);});
            Check("Waking preserves earned energy and cannot grant another reward",()=>{var r=Rules();r.State.Stat("energy",30);r.Care("sleep",Now);double stars=r.State.Number("stars"),care=r.State.Number("careCount");Assert(r.Wake(Now+600000).Ok&&!r.State.Sleeping(Now+600000));Near(r.State.Stat("energy"),32.25);Near(r.State.Number("stars"),stars);Near(r.State.Number("careCount"),care);Assert(!r.Wake(Now+600001).Ok);});
            Check("Growth unlock refuses a new item without spending stars",()=>{var r=Rules();r.State.Set("stars",100);string before=r.State.ToJson();Assert(!r.Shop("cape",Now).Ok&&before==r.State.ToJson());r.State.Set("growthXp",170);Assert(r.Shop("cape",Now).Ok&&r.State.Equipped("outfit")=="cape");Near(r.State.Number("stars"),62);});
            Check("A previously owned item survives a lower imported growth stage",()=>{var r=Rules();r.State.List("owned").Add("cape");Assert(r.Shop("cape",Now).Ok&&r.State.Equipped("outfit")=="cape");Near(r.State.Number("stars"),4);});
            Check("A sleeping pet cannot consume a treat",()=>{var r=Rules();r.State.Set("stars",100);r.Shop("moonberry",Now);r.Care("sleep",Now);string before=r.State.ToJson();Assert(!r.Shop("moonberry",Now+10).Ok&&before==r.State.ToJson());});
            Check("Rare gifts cannot be farmed by repeated idle callbacks",()=>{var r=Rules();r.State.Set("careCount",3);int gifts=0;for(int i=0;i<100;i++)if(r.Surprise(Now).Ok)gifts++;Assert(gifts==1);string before=r.State.ToJson();for(int i=0;i<50;i++)Assert(!r.Surprise(Now+100).Ok);Assert(before==r.State.ToJson());r.CanWrite=false;Assert(!r.Surprise(Now+10*GameRules.Hour).Ok&&before==r.State.ToJson());});
            Check("Food preferences do not change the care balance",()=>{foreach(string food in new[]{"apple","berry","cookie","nut"}){var r=Rules();r.State.Stat("hunger",40);Assert(r.Care("feed",Now,food).Ok);Near(r.State.Stat("hunger"),74);Near(r.State.Number("careCount"),1);Near(r.State.Number("growthXp"),2);}});
            Check("A growth milestone unlocks a preserved letter",()=>{var r=Rules();r.State.Set("growthXp",34);var result=r.Care("feed",Now);Assert(result.Levels==1&&result.NewLetter&&r.State.List("letters").Count==1);});
            Console.WriteLine("ALL "+count+" CHECKS PASSED");return 0;
        }
        catch(Exception e){Console.Error.WriteLine(e);return 1;}
    }
    static SaveJournal Journal(Dictionary<string,string> store,string key)=>new SaveJournal(key,k=>store.TryGetValue(k,out var v)?v:"",(k,v)=>store[k]=v,()=>{});
}
